commands.command:
if ! getent passwd infraset-nodejs >/dev/null; then sudo useradd --system --home-dir /nonexistent --no-create-home --shell /usr/sbin/nologin infraset-nodejs; fi; sudo install -d -o root -g root -m 0755 /opt/infraset-nodejs; sudo tee /opt/infraset-nodejs/server.js >/dev/null <<'ANTRIEB_APP_EOF'
'use strict';

var http = require('http');
var body = 'infraset-nodejs';

var server = http.createServer(function (req, res) {
  res.writeHead(200, {
    'Content-Type': 'text/plain',
    'Content-Length': Buffer.byteLength(body)
  });
  res.end(body);
});

server.listen(3000, '127.0.0.1');
ANTRIEB_APP_EOF
sudo chown root:root /opt/infraset-nodejs/server.js; sudo chmod 0644 /opt/infraset-nodejs/server.js; printf 'user='; getent passwd infraset-nodejs | cut -d: -f1,3,4,6,7; printf 'app_sha256='; sha256sum /opt/infraset-nodejs/server.js | awk '{print $1}'
